INSERT INTO "Lesson" ("id", "courseId", "title", "description", "videoUrl", "durationMin", "order") VALUES ('cmwcbrpog001nq94ahog0tixd', 'cmwcbrpoe001jq94aeopavvz2', 'Estructura financiera del ecommerce', 'Margen, caja y reinversión: los números que sostienen el escalamiento.', 'https://storage.googleapis.com/gtv-videos-bucket/sample/ElephantsDream.mp4', 17, 2);
INSERT INTO "Lesson" ("id", "courseId", "title", "description", "videoUrl", "durationMin", "order") VALUES ('cmwcbrpog001pq94azyc4z6he', 'cmwcbrpoe001jq94aeopavvz2', 'Operaciones y stock a escala', 'Inventario, proveedores y tiempos sin romper la promesa.', 'https://storage.googleapis.com/gtv-videos-bucket/sample/Sintel.mp4', 16, 3);
INSERT INTO "Lesson" ("id", "courseId", "title", "description", "videoUrl", "durationMin", "order") VALUES ('cmwcbrpoh001rq94a3hw351f5', 'cmwcbrpoe001jq94aeopavvz2', 'Fidelización y LTV', 'Venderle de nuevo a quien ya te compró: el activo olvidado.', 'https://storage.googleapis.com/gtv-videos-bucket/sample/TearsOfSteel.mp4', 15, 4);
INSERT INTO "Lesson" ("id", "courseId", "title", "description", "videoUrl", "durationMin", "order") VALUES ('cmwcbrpoi001tq94a69tyo2if', 'cmwcbrpoe001jq94aeopavvz2', 'Plan de crecimiento', 'Tu roadmap de 12 meses hacia la siguiente cifra.', 'https://storage.googleapis.com/gtv-videos-bucket/sample/ForBiggerEscapes.mp4', 20, 5);
INSERT INTO "Post" ("id", "userId", "content", "image", "createdAt", "updatedAt") VALUES ('cmwcbrpzu002tq94aesw8zj2e', 'cmwcbrpvw0021q94albpn3osz', 'El programa de Escalado a 7 Cifras me voló la cabeza. Números reales, ejemplos reales, cero humo. Recomendado para cualquiera que ya venda y quiera montar sistemas en vez de vivir apagando incendios. Lo estoy viendo por segunda vez y tomando notas distintas.', NULL, '2026-11-06T16:20:08.154+00:00', '2026-11-11T16:20:08.155+00:00');
INSERT INTO "Post" ("id", "userId", "content", "image", "createdAt", "updatedAt") VALUES ('cmwcbrpzu002rq94amyeq9i0b', 'cmwcbrpqk001vq94ay8lqngje', 'Pregunta rápida para los que venden en Latam: qué pasarela están usando? Estoy evaluando cambiar porque los retrasos de liquidación me complican el flujo de caja para comprar inventario. Experiencias reales, por favor.', NULL, '2026-11-07T12:20:08.153+00:00', '2026-11-11T16:20:08.154+00:00');
INSERT INTO "Post" ("id", "userId", "content", "image", "createdAt", "updatedAt") VALUES ('cmwcbrpzt002pq94a8ewsi7x8', 'cmwcbrpws0022q94awx2i3maz', 'Primera comisión de afiliado: $47 dólares. Para muchos es poco; para mí es la prueba de que el modelo funciona. El orgullo no me deja dormir. La racha sigue, siguiente meta: la primera comisión recurrente de la semana.', NULL, '2026-11-08T03:20:08.153+00:00', '2026-11-11T16:20:08.154+00:00');
INSERT INTO "Post" ("id", "userId", "content", "image", "createdAt", "updatedAt") VALUES ('cmwcbrpzs002nq94ahg8n1ayf', 'cmwcbrpxp0023q94aix96zlxp', 'Me acabo de crear la cuenta y completé mi perfil. Qué emoción empezar de cero con ustedes. Recomendación: por dónde empiezo, primero el programa de ecommerce o mejor el de contenidos? Mi objetivo es entender el mapa completo antes de elegir.', NULL, '2026-11-08T15:20:08.152+00:00', '2026-11-11T16:20:08.153+00:00');
INSERT INTO "Post" ("id", "userId", "content", "image", "createdAt", "updatedAt") VALUES ('cmwcbrpzs002lq94abk5m3o62', 'cmwcbrpyp0024q94asge4k54c', 'Vengo del mundo físico, tengo un restaurante, y entré al hub para digitalizar el negocio. La primera lección de Ecommerce desde Cero me despejó dudas que arrastraba hace meses. Alguien más dando el salto de lo tradicional a lo digital?', NULL, '2026-11-09T02:20:08.152+00:00', '2026-11-11T16:20:08.153+00:00');
INSERT INTO "Post" ("id", "userId", "content", "image", "createdAt", "updatedAt") VALUES ('cmwcbrpzs002jq94ac46imacj', 'cmwcbrpv00020q94a8z2apvpy', 'Mi compromiso del trimestre, por escrito y frente a testigos: 10.000 seguidores y 3 clientes de branding. Voy a publicar mi avance cada lunes en este muro para no perderme. Quien quiera, me acompaña y me exige cuando toque.', NULL, '2026-11-09T13:20:08.152+00:00', '2026-11-11T16:20:08.152+00:00');
INSERT INTO "Post" ("id", "userId", "content", "image", "createdAt", "updatedAt") VALUES ('cmwcbrpzs002hq94au81cmcna', 'cmwcbrpt9001yq94ans8z4416', 'Día 12 probando el producto que elegí para mi dropsi. Primera venta a las 6:40 de la mañana. Una sola. Y la celebré como si fueran mil. Así se empieza, ¿verdad? Alguien más en etapa de validación para compartir números sin filtros?', NULL, '2026-11-09T20:20:08.151+00:00', '2026-11-11T16:20:08.152+00:00');
INSERT INTO "Post" ("id", "userId", "content", "image", "createdAt", "updatedAt") VALUES ('cmwcbrpzr002fq94a6x1rs89d', 'cmwcbrpu5001zq94a8aqmpbzf', 'Les comparto un mini marco de copy que me está funcionando en emails: 1) dolor real, 2) promesa concreta, 3) prueba, 4) una sola llamada a la acción. Mi último email abrió al 41%. El CopyLab IA me ayuda a generar variantes en segundos y después las pulo a mano. Aliado silencioso.', NULL, '2026-11-10T10:20:08.151+00:00', '2026-11-11T16:20:08.152+00:00');
INSERT INTO "Post" ("id", "userId", "content", "image", "createdAt", "updatedAt") VALUES ('cmwcbrpzr002dq94a37664ylp', 'cmwcbrpvw0021q94albpn3osz', 'Herramienta del día: usé la Calculadora de Precios antes de lanzar mi nueva línea de serums y descubrí que estaba dejando 23% de margen sobre la mesa. Si venden producto físico, no lancen nada sin calcular bien envío y comisión de pasarela. Los números primero, la emoción después.', NULL, '2026-11-10T18:20:08.151+00:00', '2026-11-11T16:20:08.151+00:00');
INSERT INTO "Post" ("id", "userId", "content", "image", "createdAt", "updatedAt") VALUES ('cmwcbrpzr002bq94ad9psd3m6', 'cmwcbrpsd001xq94a0wm5r34n', 'Terminé el programa de Marketing de Contenidos en una semana. Cinco lecciones que valen oro. Mi takeaway: constancia antes que perfección. Este mes publiqué 22 reels y dupliqué alcance sin gastar un peso en ads. Gracias ALQEMIA por un sistema tan claro.', NULL, '2026-11-11T02:20:08.150+00:00', '2026-11-11T16:20:08.151+00:00');
INSERT INTO "Post" ("id", "userId", "content", "image", "createdAt", "updatedAt") VALUES ('cmwcbrpzq0029q94ahferbqwl', 'cmwcbrpri001wq94a2d1d43td', 'Pregunta para los que ya escalan: en qué momento decidieron duplicar presupuesto? Llevo 3 días con un CPA estable de $4.20 y tengo miedo de romper la magia. Aportes bienvenidos, prometo devolver el favor con lo que aprenda del experimento.', NULL, '2026-11-11T09:20:08.150+00:00', '2026-11-11T16:20:08.151+00:00');
INSERT INTO "Post" ("id", "userId", "content", "image", "createdAt", "updatedAt") VALUES ('cmwcbrpzp0027q94an6tfeoqy', 'cmwcbrpqk001vq94ay8lqngje', 'Checkpoint de la semana: cerramos la mejor semana desde que lancé la tienda. 32 órdenes y un ROAS de 3.4. La lección que me lo cambió todo fue la de escalado del Máster en Meta Ads: no toques la creativa ganadora hasta pasar las 50 conversiones. Si están en campaña, eso evita muchos dolores de cabeza.', NULL, '2026-11-11T13:20:08.149+00:00', '2026-11-11T16:20:08.150+00:00');
INSERT INTO "Comment" ("id", "postId", "userId", "content", "createdAt") VALUES ('cmwcbrq02003pq94a7faj9yd3', 'cmwcbrpzu002tq94aesw8zj2e', 'cmwcbrpri001wq94a2d1d43td', 'Ese programa es un MBA de verdad. La clase de finanzas debería ser obligatoria para todos.', '2026-11-07T02:20:08.162+00:00');
INSERT INTO "Comment" ("id", "postId", "userId", "content", "createdAt") VALUES ('cmwcbrq02003nq94aayoh2mtr', 'cmwcbrpzu002rq94amyeq9i0b', 'cmwcbrpri001wq94a2d1d43td', 'Depende del país. Para flujo de caja rápido mira las que liquidan en 48-72h aunque cobren un poco más.', '2026-11-07T22:20:08.161+00:00');
INSERT INTO "Comment" ("id", "postId", "userId", "content", "createdAt") VALUES ('cmwcbrq01003lq94an2mgnrsv', 'cmwcbrpzt002pq94a8ewsi7x8', 'cmwcbrpu5001zq94a8aqmpbzf', '47 dólares que valen más que cualquier curso motivacional. Felicidades!', '2026-11-08T18:20:08.161+00:00');
INSERT INTO "Comment" ("id", "postId", "userId", "content", "createdAt") VALUES ('cmwcbrq00003hq94ag88y7sy9', 'cmwcbrpzs002nq94ahg8n1ayf', 'cmwcbrpqk001vq94ay8lqngje', 'Bienvenida Isabela! Mi consejo: ecommerce primero si quieres vender producto, contenidos primero si quieres audiencia. Decide por el negocio, no por el gustito.', '2026-11-09T04:20:08.160+00:00');
INSERT INTO "Comment" ("id", "postId", "userId", "content", "createdAt") VALUES ('cmwcbrq01003jq94anorp1cx7', 'cmwcbrpzs002nq94ahg8n1ayf', 'cmwcbrpsd001xq94a0wm5r34n', 'Coincido con Valeria. Y completa el perfil para que la comunidad sepa quién eres.', '2026-11-09T06:20:08.161+00:00');
INSERT INTO "Comment" ("id", "postId", "userId", "content", "createdAt") VALUES ('cmwcbrq00003fq94azm9jxln6', 'cmwcbrpzs002jq94ac46imacj', 'cmwcbrpsd001xq94a0wm5r34n', 'Te exijo los lunes. Este muro será testigo.', '2026-11-09T19:20:08.160+00:00');
INSERT INTO "Comment" ("id", "postId", "userId", "content", "createdAt") VALUES ('cmwcbrpzz003bq94a4osss1j4', 'cmwcbrpzs002hq94au81cmcna', 'cmwcbrpws0022q94awx2i3maz', 'Así se empieza. Mi primera comisión también fue sola y fue la mejor notificación del año.', '2026-11-10T02:20:08.159+00:00');
INSERT INTO "Comment" ("id", "postId", "userId", "content", "createdAt") VALUES ('cmwcbrpzz003dq94ay2w713co', 'cmwcbrpzs002hq94au81cmcna', 'cmwcbrpyp0024q94asge4k54c', 'Ánimo! Yo voy 14 días sin venta pero el punto es seguir probando. Nos vamos a comparar resultados.', '2026-11-10T04:20:08.159+00:00');
INSERT INTO "Comment" ("id", "postId", "userId", "content", "createdAt") VALUES ('cmwcbrpzz0039q94am5i6mtgs', 'cmwcbrpzr002fq94a6x1rs89d', 'cmwcbrpv00020q94a8z2apvpy', 'El punto 4 es el más difícil: una sola CTA. En branding siempre quiero vender tres cosas a la vez.', '2026-11-10T15:20:08.159+00:00');
INSERT INTO "Comment" ("id", "postId", "userId", "content", "createdAt") VALUES ('cmwcbrpzy0037q94afxs3ahs6', 'cmwcbrpzr002dq94a37664ylp', 'cmwcbrpt9001yq94ans8z4416', 'La calculadora me reveló lo mismo con envíos. Casi lanzo regalando dinero.', '2026-11-10T22:20:08.158+00:00');
INSERT INTO "Comment" ("id", "postId", "userId", "content", "createdAt") VALUES ('cmwcbrpzy0035q94a1wvkx4jr', 'cmwcbrpzr002bq94ad9psd3m6', 'cmwcbrpxp0023q94aix96zlxp', 'Tu post me acaba de decidir: empiezo por contenidos. Gracias por compartir tu resultado.', '2026-11-11T06:20:08.157+00:00');
INSERT INTO "Comment" ("id", "postId", "userId", "content", "createdAt") VALUES ('cmwcbrpzw0031q94aegnhdnf7', 'cmwcbrpzq0029q94ahferbqwl', 'cmwcbrpvw0021q94albpn3osz', 'Si llevas 3 días estable, sube 20% y espera 72 horas. Es lo que me funcionó con serums.', '2026-11-11T11:20:08.156+00:00');
INSERT INTO "Comment" ("id", "postId", "userId", "content", "createdAt") VALUES ('cmwcbrpzx0033q94asmpvi9j5', 'cmwcbrpzq0029q94ahferbqwl', 'cmwcbrpqk001vq94ay8lqngje', 'El miedo a romperlo es real. Pero recuerda: si funciona, se puede reconstruir. Si nunca escalas, no hay nada que reconstruir.', '2026-11-11T12:20:08.156+00:00');
INSERT INTO "Comment" ("id", "postId", "userId", "content", "createdAt") VALUES ('cmwcbrpzu002vq94ai3m6c3v3', 'cmwcbrpzp0027q94an6tfeoqy', 'cmwcbrpri001wq94a2d1d43td', 'Apliqué esa regla y me salvó una campaña que llevaba $800. La regla de las 50 es sagrada.', '2026-11-11T14:20:08.154+00:00');
INSERT INTO "Comment" ("id", "postId", "userId", "content", "createdAt") VALUES ('cmwcbrpzv002xq94autle376x', 'cmwcbrpzp0027q94an6tfeoqy', 'cmwcbrpvw0021q94albpn3osz', 'Ese ROAS con moda es para aplaudir. El margen de moda castiga, bien ahí.', '2026-11-11T15:20:08.155+00:00');
INSERT INTO "Comment" ("id", "postId", "userId", "content", "createdAt") VALUES ('cmwcbrpzw002zq94adx87zx1s', 'cmwcbrpzp0027q94an6tfeoqy', 'cmwcbrpsd001xq94a0wm5r34n', 'Anotando la regla de las 50. Gracias por compartir el número real.', '2026-11-11T15:20:08.155+00:00');
